      "content": "// dsh/client.js — DSH Client 半边
//
// 在 `conversation.input.right` Slot (与 dsh-musage 同一位置: composer 卡内,
// model select 紧邻左侧) 渲染 Command Code 套餐用量: 5h 窗口已用% | 周窗口
// 已用% | 剩余 credits。数据来自 @mars-sea/dsh-commandcode-provider 已经
// mount 好的 `commandcode/report` Remote (accounts[].report.credits /
// .plan / .account), 本插件只做展示, 不重复请求 Command Code API。
//
// 行为:
//   - 当前会话 provider 是 commandcode 时显示徽章; 其它 provider 隐藏
//     (不占位, 不挡 dsh-musage 对它支持的 5 家 provider 的显示)。
//   - 多账户: 优先显示 active 账户; 没有 active 标记时显示第一个
//     configured 账户; hover 展开各账户明细。
//   - 60s 轮询 + 手动刷新 (点击)。
//   - 任何异常静默降级: 显示 Command Code ⚠, hover 看原因。

window.__ModuleLoader__.load({
  id: "dsh-commandcode-usage-inline",
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;

    var React = require("react");

    const REFRESH_INTERVAL_MS = 60_000;

    // ---- commandcode/report 结果边界校验 (宽容: 缺段跳过, 不抛) ----

    function num(v) {
      return typeof v === "number" && Number.isFinite(v) ? v : 0;
    }
    function bool(v) {
      return v === true;
    }
    function str(v) {
      return typeof v === "string" ? v : "";
    }
    function windowLimit(value) {
      if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
      return {
        used: num(value.used),
        cap: num(value.cap),
        exceeded: bool(value.exceeded),
        resetAt: num(value.resetAt),
      };
    }
    function parseUsageReport(value) {
      if (typeof value !== "object" || value === null || Array.isArray(value)) return null;
      const source = value;
      const report = { failures: Array.isArray(source.failures) ? source.failures.filter((f) => typeof f === "string") : [] };
      if (typeof source.blocked === "string") report.blocked = source.blocked;
      if (source.account && typeof source.account === "object") {
        report.account = {
          id: str(source.account.id),
          name: str(source.account.name),
          userName: str(source.account.userName),
        };
      }
      if (source.credits && typeof source.credits === "object") {
        report.credits = {
          monthlyCredits: num(source.credits.monthlyCredits),
          purchasedCredits: num(source.credits.purchasedCredits),
          freeCredits: num(source.credits.freeCredits),
          fiveHour: windowLimit(source.credits.fiveHour),
          weekly: windowLimit(source.credits.weekly),
        };
      }
      if (source.plan && typeof source.plan === "object") {
        report.plan = {
          planId: str(source.plan.planId),
          name: str(source.plan.name),
          status: str(source.plan.status),
          monthlyCredits: typeof source.plan.monthlyCredits === "number" ? source.plan.monthlyCredits : null,
          currentPeriodEnd: num(source.plan.currentPeriodEnd),
        };
      }
      return report;
    }
    function parseAccountsReport(value) {
      const result = typeof value === "object" && value !== null ? value : null;
      const accounts = result && Array.isArray(result.accounts) ? result.accounts : null;
      if (!accounts) return { accounts: [] };
      return {
        accounts: accounts.map((a) => {
          if (typeof a !== "object" || a === null) return null;
          return {
            id: str(a.id),
            label: str(a.label),
            configured: bool(a.configured),
            active: bool(a.active),
            mark: str(a.mark),
            cooldownUntil: num(a.cooldownUntil),
            report: parseUsageReport(a.report),
          };
        }).filter(Boolean),
      };
    }

    // ---- 展示工具 ----

    function pct(used, cap) {
      if (!cap || cap <= 0) return null;
      return Math.max(0, Math.min(100, Math.round((used / cap) * 100)));
    }

    function remainingCredits(d) {
      if (!d) return null;
      return d.purchasedCredits + d.freeCredits;
    }

    function resetsIn(resetAtMs) {
      if (!resetAtMs || resetAtMs <= 0) return "";
      const ms = resetAtMs - Date.now();
      if (ms <= 0) return "即将重置";
      const totalMin = Math.floor(ms / 60000);
      const h = Math.floor(totalMin / 60);
      const m = totalMin % 60;
      if (h > 0) return h + "h" + m + "m重置";
      return m + "m重置";
    }

    function pickAccount(accounts) {
      const configured = accounts.filter((a) => a.configured && a.report);
      if (configured.length === 0) return null;
      const active = configured.find((a) => a.active);
      return active || configured[0];
    }

    const CC_LABEL = "Command Code";

    function Badge(props) {
      const { state, onRefresh } = props;
      const [open, setOpen] = React.useState(false);
      // 幂等注入 hover 样式 (一次即可)
      if (!Badge._cssInjected) {
        Badge._cssInjected = true;
        try {
          const styleTag = document.createElement("style");
          styleTag.dataset.plugin = "dsh-commandcode-usage";
          styleTag.textContent = [
            "[data-ccu=badge]{transition:background .12s ease,border-radius .12s ease}",
            "[data-ccu=badge]:hover{background:var(--dsw-alias-interactive-bg-hover,rgba(128,128,128,.14));border-radius:999px}",
            "[data-ccu=btn]{transition:background .12s ease,color .12s ease,transform .05s ease}",
            "[data-ccu=btn]:hover{background:var(--dsw-alias-interactive-bg-hover-strong,rgba(128,128,128,.28))!important;color:var(--dsw-alias-label-primary,#fff)!important}",
            "[data-ccu=btn]:active{transform:scale(.97)}",
          ].join("\n");
          (document.head || document.documentElement).appendChild(styleTag);
        } catch (e) {}
      }
      const toggle = (e) => {
        if (e && e.stopPropagation) e.stopPropagation();
        setOpen(!open);
      };
      const containerStyle = {
        display: "inline-flex",
        alignItems: "center",
        marginLeft: "auto",
        gap: 4,
        padding: "2px 8px",
        fontSize: 11,
        fontVariantNumeric: "tabular-nums",
        userSelect: "none",
        cursor: "pointer",
        position: "relative",
      };
      const muted = "var(--dsh-text-muted, #888)";
      const strong = "var(--dsh-text, #eee)";

      // 点击徽章展开的详情浮层: 向上弹出 (bottom: calc(100%+8px), 同模型选择浮窗),
      // 并复用 DSH 设计令牌 (--dsw-*) 使外观与右侧模型选择浮窗一致。
      // 限高: 内容超出一屏高度时内部滚动, 避免浮层过高。
      const popoverStyle = {
        position: "absolute",
        bottom: "calc(100% + 8px)",
        right: 0,
        zIndex: 9999,
        width: "max-content",
        minWidth: 230,
        maxWidth: "min(380px, calc(100vw - 32px))",
        maxHeight: "min(320px, calc(100vh - 96px))",
        padding: 4,
        fontSize: 11,
        lineHeight: "14px",
        textAlign: "left",
        whiteSpace: "nowrap",
        color: "var(--dsw-alias-label-primary, var(--dsh-text, #eee))",
        background: "var(--dsw-specific-menu, var(--dsh-bg-elevated, #1e1f24))",
        boxShadow: "var(--dsw-elevation-prominent, 0 6px 20px rgba(0,0,0,.35))",
        border: "0",
        borderRadius: 12,
        flexDirection: "column",
        display: "flex",
        gap: 1,
        overflowY: "auto",
        overflowX: "hidden",
      };
      // 紧凑行: 固定内容盒高度, 避免被继承行高/字体撑高。
      const rowStyle = {
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 10,
        padding: "2px 8px",
        minHeight: 20,
        boxSizing: "border-box",
        borderRadius: 7,
        fontSize: 11,
        lineHeight: "14px",
        whiteSpace: "nowrap",
        flex: "none",
      };
      const rowKey = { color: "var(--dsw-alias-label-secondary, var(--dsh-text-muted, #888))", flex: "none", lineHeight: "14px", fontSize: 11 };
      const rowVal = { color: "var(--dsw-alias-label-primary, var(--dsh-text, #eee))", fontWeight: 600, fontVariantNumeric: "tabular-nums", lineHeight: "14px", fontSize: 11, overflow: "hidden", textOverflow: "ellipsis", minWidth: 0, maxWidth: "70%" };
      const btnStyle = {
        flex: 1,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "2px 10px",
        minHeight: 22,
        boxSizing: "border-box",
        fontSize: 11,
        lineHeight: "14px",
        cursor: "pointer",
        borderRadius: 7,
        border: "none",
        background: "var(--dsw-alias-interactive-bg-hover, rgba(128,128,128,.15))",
        color: "inherit",
      };
      const detailRow = (k, v, key) => React.createElement(
        "div",
        { key, style: rowStyle },
        React.createElement("span", { style: rowKey }, k),
        React.createElement("span", { style: rowVal }, v)
      );
      const kv = detailRow;
      const dot = (color) => ({ display: "inline-block", width: 6, height: 6, borderRadius: 3, marginRight: 6, background: color, flex: "none" });

      // 加载中
      if (!state.loaded) {
        return React.createElement(
          "div",
          { "data-ccu": "badge", style: Object.assign({}, containerStyle, { color: muted }) },
          React.createElement("span", { style: { fontWeight: 500 } }, "CC"),
          React.createElement("span", { style: { opacity: 0.6, fontSize: 10 } }, "···")
        );
      }

      // 失败: 点击看错误
      if (!state.ok) {
        return React.createElement(
          "div",
          {
            "data-ccu": "badge",
            style: Object.assign({}, containerStyle, { color: "var(--dsh-text-warning, #f5a623)" }),
            onClick: toggle,
          },
          React.createElement("span", { style: { fontWeight: 500 } }, "CC"),
          React.createElement("span", { style: { fontWeight: 600 } }, "⚠"),
          open
            ? React.createElement(
                "div",
                { style: popoverStyle, onClick: (e) => e.stopPropagation() },
                React.createElement(
                  "div",
                  { style: Object.assign({}, rowStyle, { background: "var(--dsw-alias-interactive-bg-hover-danger, rgba(200,60,50,.15))", color: "var(--dsw-alias-state-error-primary, #f66)", fontWeight: 600 }) },
                  "Command Code 用量获取失败"
                ),
                kv("原因", state.message || "unknown", "err"),
                React.createElement(
                  "div",
                  { key: "actions", style: { display: "flex", gap: 6, padding: "4px 4px 2px" } },
                  React.createElement(
                    "button",
                    { "data-ccu": "btn", onClick: (e) => { e.stopPropagation(); onRefresh(); }, style: btnStyle },
                    "重试"
                  )
                )
              )
            : null
        );
      }

      const account = pickAccount(state.accounts || []);
      if (!account || !account.report) {
        return React.createElement(
          "div",
          { "data-ccu": "badge", style: Object.assign({}, containerStyle, { color: muted }) },
          React.createElement("span", { style: { fontWeight: 500 } }, "CC")
        );
      }

      const report = account.report;
      const credits = report.credits || null;
      const five = credits ? credits.fiveHour : null;
      const week = credits ? credits.weekly : null;
      const fivePct = five ? pct(five.used, five.cap) : null;
      const weekPct = week ? pct(week.used, week.cap) : null;
      const remain = remainingCredits(credits);
      // 前缀: 默认账户用简短 "CC"; 多账户(非 Default)时显示账户 label。
      const label = account.label && account.label !== "Default" ? account.label : "CC";

      const others = (state.accounts || []).filter((a) => a.configured && a !== account);

      // 详情浮层内容
      const detailChildren = [];
      detailChildren.push(
        React.createElement(
          "div",
          {
            key: "head",
            style: Object.assign({}, rowStyle, { background: "var(--dsw-alias-bg-module, rgba(128,128,128,.08))", fontWeight: 700, justifyContent: "flex-start" }),
          },
          React.createElement("span", { style: dot(account.active ? "#4caf50" : "#888") }),
          "Command Code" + (account.active ? " · 当前账户" : "") + (label !== "CC" ? " (" + label + ")" : "")
        )
      );
      if (report.plan && report.plan.name) detailChildren.push(kv("套餐", report.plan.name, "plan"));
      if (five) {
        detailChildren.push(kv(
          "5h 窗口",
          (fivePct === null ? "—" : fivePct + "% 已用") +
            (five.exceeded ? " · 已超限" : "") +
            (five.resetAt ? " · " + resetsIn(five.resetAt) : ""),
          "five"
        ));
      }
      if (week) {
        detailChildren.push(kv(
          "周窗口",
          (weekPct === null ? "—" : weekPct + "% 已用") +
            (week.exceeded ? " · 已超限" : "") +
            (week.resetAt ? " · " + resetsIn(week.resetAt) : ""),
          "week"
        ));
      }
      if (credits) {
        detailChildren.push(kv(
          "剩余 credits",
          (remain === null ? "—" : String(remain)),
          "remain"
        ));
        detailChildren.push(kv(
          "构成",
          "订阅 " + credits.monthlyCredits + " + 购买 " + credits.purchasedCredits + " + 免费 " + credits.freeCredits,
          "compose"
        ));
      }
      for (const other of others) {
        const oc = other.report && other.report.credits ? other.report.credits : null;
        const or5 = oc && oc.fiveHour ? pct(oc.fiveHour.used, oc.fiveHour.cap) : null;
        const owk = oc && oc.weekly ? pct(oc.weekly.used, oc.weekly.cap) : null;
        detailChildren.push(kv(
          "账户 " + other.label,
          "5h " + (or5 === null ? "—" : or5 + "%") + " · 周 " + (owk === null ? "—" : owk + "%"),
          "other-" + other.id
        ));
      }
      for (const failure of report.failures || []) {
        detailChildren.push(
          React.createElement(
            "div",
            { key: "f-" + failure, style: Object.assign({}, rowStyle, { color: "var(--dsw-alias-state-warn-label, #f5a623)" }) },
            "⚠ " + failure
          )
        );
      }
      detailChildren.push(
        React.createElement(
          "div",
          { key: "actions", style: { display: "flex", gap: 6, padding: "4px 4px 2px" } },
          React.createElement(
            "button",
            { "data-ccu": "btn", onClick: (e) => { e.stopPropagation(); onRefresh(); }, style: btnStyle },
            "刷新"
          ),
          React.createElement(
            "button",
            { "data-ccu": "btn", onClick: (e) => { e.stopPropagation(); setOpen(false); }, style: btnStyle },
            "关闭"
          )
        )
      );

      return React.createElement(
        "div",
        { "data-ccu": "badge", style: Object.assign({}, containerStyle, { color: muted }), onClick: toggle },
        React.createElement("span", { style: { fontWeight: 500 } }, label),
        fivePct !== null
          ? React.createElement("span", { style: { fontWeight: 600, color: five.exceeded ? "var(--dsh-text-danger, #f66)" : strong } }, "5h " + fivePct + "%")
          : null,
        fivePct !== null && weekPct !== null
          ? React.createElement("span", { style: { opacity: 0.5, fontSize: 10 } }, "|")
          : null,
        weekPct !== null
          ? React.createElement("span", { style: { fontWeight: 600, color: week.exceeded ? "var(--dsh-text-danger, #f66)" : strong } }, "周 " + weekPct + "%")
          : null,
        remain !== null
          ? React.createElement("span", { style: { fontWeight: 600, color: strong } }, "剩 " + remain)
          : null,
        open
          ? React.createElement("div", { style: popoverStyle, onClick: (e) => e.stopPropagation() }, ...detailChildren)
          : null
      );
    }

    // ---- provider 跟随: 只在当前会话 provider 是 commandcode 时显示 ----

    function readActiveProvider(snapshot) {
      if (!snapshot) return null;
      const cur = snapshot.current;
      if (!cur) return null;
      const route = cur.provider;
      if (!route) return null;
      return route === "commandcode" ? "commandcode" : null;
    }

    function apply(ctx) {
      const slots = ctx.slots;
      if (!slots || typeof slots.inject !== "function") {
        console.log("[commandcode-usage] skip: slots service 不可用");
        return;
      }
      const timer = ctx.timer;
      const models = ctx.modelDirectories;

      // 关键: remote 的命名空间属性 (remote.commandcode) 只能通过
      // ctx.inject(["remote.commandcode"]) 授权读取, 直接 ctx.get("remote")
      // 后读 .commandcode 会被代理拦 ("cannot get property ... without inject")。
      //
      // provider 客户端在自己的 $mount 完成前不会提供 commandcode 命名空间;
      // 而我们 apply 的时序可能早于它。因此这里:
      //   1) 尝试幂等 $mount: 若 provider 已挂载同一 method, validateContribution
      //      会抛 "already mounted" —— 这正是"provider 已经建好命名空间"的信号,
      //      捕获后继续走嵌套 inject 复用即可。
      //   2) $mount resolve (或捕获 already-mounted) 后, 命名空间服务必已注册,
      //      再嵌套 inject 授权读取。
      let usageNamespace = null;
      let usageMountError = null;
      let ensureStarted = null;

      function startEnsure() {
        if (ensureStarted) return ensureStarted;
        ensureStarted = ctx.inject(["remote"], async (remoteCtx) => {
          const remote = remoteCtx.remote;
          try {
            await remote.$mount({
              package: "@mars-sea/dsh-commandcode-provider",
              descriptors: [{
                id: "dsh-commandcode-usage#commandcode/report",
                service: "commandcodeUsage",
                namespace: "commandcode",
                method: "report",
                invocation: { kind: "direct" },
                parameters: [],
                result: {
                  mode: "strict",
                  typeSymbol: "@mars-sea/dsh-commandcode-provider#CommandCodeAccountsReport",
                  schema: { parse: parseAccountsReport },
                },
              }],
            });
